<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { request } from '@/api/client'
import type { BudgetComponent, Claim, ClaimItem } from '@/types/simbg'

const route = useRoute(); const router = useRouter(); const claimId = computed(() => String(route.params.id)); const itemId = computed(() => String(route.params.itemId || '')); const editing = computed(() => Boolean(itemId.value))
const components = ref<BudgetComponent[]>([]); const form = reactive({ budgetComponentId: '', description: '', quantity: 1, unitPrice: 0 }); const error = ref(''); const saving = ref(false)
onMounted(async () => { try { const claim = await request<Claim>(`/claim/${claimId.value}`); if (claim.anggaranId) components.value = await request<BudgetComponent[]>(`/anggaran/${claim.anggaranId}/komponen`); if (editing.value) { const item = await request<ClaimItem>(`/claim/${claimId.value}/item/${itemId.value}`); form.budgetComponentId = item.budgetComponentId; form.description = item.description; form.quantity = item.quantity; form.unitPrice = item.unitPrice } } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Gagal memuat data item.' } })
async function submit() { saving.value = true; error.value = ''; try { const path = `/claim/${claimId.value}/item${editing.value ? `/${itemId.value}` : ''}`; await request<ClaimItem>(path, { method: editing.value ? 'PUT' : 'POST', body: JSON.stringify(form) }); await router.push(`/claim/${claimId.value}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Gagal menyimpan item claim.' } finally { saving.value = false } }
</script>

<template><main class="page narrow"><RouterLink class="back-link" :to="`/claim/${claimId}`">← Kembali ke detail claim</RouterLink><header class="page-header"><div><p class="eyebrow">Item Claim · {{ claimId }}</p><h1>{{ editing ? 'Ubah Claim Item' : 'Tambah Claim Item' }}</h1><p class="subtitle">Jumlah item dihitung dari kuantitas × harga satuan.</p></div></header><form class="form-card" @submit.prevent="submit"><label>Komponen anggaran<select v-model="form.budgetComponentId" required><option value="" disabled>Pilih komponen</option><option v-for="component in components" :key="component.id" :value="component.id">{{ component.componentName }} · maks. {{ new Intl.NumberFormat('id-ID').format(component.maxRate) }}/unit</option></select></label><label>Deskripsi<input v-model.trim="form.description" required></label><div class="form-grid"><label>Kuantitas<input v-model.number="form.quantity" type="number" min="1" required></label><label>Harga satuan (Rp)<input v-model.number="form.unitPrice" type="number" min="1" required></label></div><div class="calculated-total"><span>Perkiraan jumlah</span><strong>{{ new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(form.quantity * form.unitPrice) }}</strong></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="form-actions"><RouterLink class="button button-secondary" :to="`/claim/${claimId}`">Batal</RouterLink><button class="button" :disabled="saving">{{ saving ? 'Menyimpan…' : 'Simpan Item' }}</button></div></form></main></template>
